private void convert(int value, int from, int length) {
	int index = from + BITS_PER_CHAR;
	while (value != 0L && length > 0) {
		if (value % 2L != 0) {
			fBitVector.set(index);
		}
		index--;
		value = value >>> 1;
		length--;
	}
}

